#include <iostream>
#include <vector>
#include <cassert>
#include <cmath>
#include <algorithm>
using namespace std;

using i64 = long long;
constexpr i64 MOD = 1000000007;

template<typename T>
class Matrix {
public:
    vector<vector<T>> data;

    Matrix() = default;

    Matrix(size_t rows, size_t cols) : data(rows, vector<T>(cols, 0)) {}

    Matrix(size_t n) : data(n, vector<T>(n, 0)) {}

    size_t height() const { return data.size(); }
    size_t width() const { return data.empty() ? 0 : data[0].size(); }

    const vector<T>& operator[](size_t idx) const { return data[idx]; }
    vector<T>& operator[](size_t idx) { return data[idx]; }

    static Matrix identity_matrix(size_t n) {
        Matrix res(n);
        for (size_t i = 0; i < n; ++i) res[i][i] = 1;
        return res;
    }

    Matrix& operator+=(const Matrix& other) {
        assert(height() == other.height() && width() == other.width());
        for (size_t i = 0; i < height(); ++i)
            for (size_t j = 0; j < width(); ++j)
                data[i][j] = (data[i][j] + other[i][j]) % MOD;
        return *this;
    }

    Matrix& operator-=(const Matrix& other) {
        assert(height() == other.height() && width() == other.width());
        for (size_t i = 0; i < height(); ++i)
            for (size_t j = 0; j < width(); ++j)
                data[i][j] = (data[i][j] - other[i][j] + MOD) % MOD;
        return *this;
    }

    Matrix& operator*=(const Matrix& other) {
        size_t r = height(), c = other.width(), m = width();
        assert(m == other.height());
        vector<vector<T>> temp(r, vector<T>(c, 0));
        for (size_t i = 0; i < r; ++i)
            for (size_t k = 0; k < m; ++k)
                for (size_t j = 0; j < c; ++j)
                    temp[i][j] = (temp[i][j] + data[i][k] * other[k][j]) % MOD;
        data = move(temp);
        return *this;
    }

    Matrix& operator^=(i64 exponent) {
        Matrix result = identity_matrix(height());
        Matrix base = *this;
        while (exponent > 0) {
            if (exponent & 1) result *= base;
            base *= base;
            exponent >>= 1;
        }
        data = move(result.data);
        return *this;
    }

    Matrix operator+(const Matrix& other) const { Matrix tmp(*this); tmp += other; return tmp; }
    Matrix operator-(const Matrix& other) const { Matrix tmp(*this); tmp -= other; return tmp; }
    Matrix operator*(const Matrix& other) const { Matrix tmp(*this); tmp *= other; return tmp; }
    Matrix operator^(i64 exponent) const { Matrix tmp(*this); tmp ^= exponent; return tmp; }

    friend ostream& operator<<(ostream& os, const Matrix& m) {
        for (size_t i = 0; i < m.height(); ++i) {
            os << "[";
            for (size_t j = 0; j < m.width(); ++j) {
                os << m[i][j] << (j + 1 == m.width() ? "]\n" : ",");
            }
        }
        return os;
    }

    T compute_determinant() {
        Matrix<T> copy(*this);
        assert(height() == width());
        T det = 1;
        size_t n = height();
        for (size_t i = 0; i < n; ++i) {
            int pivot = -1;
            for (size_t j = i; j < n; ++j) {
                if (copy[j][i] != 0) {
                    pivot = j;
                    break;
                }
            }
            if (pivot == -1) return 0;
            if (i != pivot) {
                det = (det * (MOD - 1)) % MOD;
                swap(copy[i], copy[pivot]);
            }
            det = (det * copy[i][i]) % MOD;
            T inv = mod_inverse(copy[i][i], MOD);
            for (size_t j = 0; j < n; ++j) {
                copy[i][j] = (copy[i][j] * inv) % MOD;
            }
            for (size_t j = i + 1; j < n; ++j) {
                T factor = copy[j][i];
                for (size_t k = 0; k < n; ++k) {
                    copy[j][k] = (copy[j][k] - copy[i][k] * factor) % MOD;
                    if (copy[j][k] < 0) copy[j][k] += MOD;
                }
            }
        }
        return (det % MOD + MOD) % MOD;
    }

private:
    T mod_inverse(T a, T mod) {
        T m = mod, x = 0, y = 1;
        if (mod == 1) return 0;
        while (a > 1) {
            T q = a / mod;
            T t = mod;
            mod = a % mod;
            a = t;
            t = x;
            x = y - q * x;
            y = t;
        }
        if (y < 0) y += m;
        return y;
    }

public:
    void cyclic_shift() {
        Matrix<T> temp(height());
        for (size_t i = 0; i < K; ++i) {
            for (size_t j = 0; j < K; ++j) {
                temp[i][j] = data[(i + K - 1) % K][(j + K - 1) % K];
            }
            temp[i][K] = data[(i + K - 1) % K][K];
            temp[K][i] = data[K][(i + K - 1) % K];
        }
        temp[K][K] = data[K][K];
        data = move(temp.data);
    }
};

Matrix<i64> table[70][35];

i64 fast_pow(i64 base, i64 exp) {
    if (exp == 0) return 1;
    i64 half = fast_pow(base, exp / 2);
    i64 result = (half * half) % MOD;
    if (exp & 1) result = (result * base) % MOD;
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    i64 N_input, K_input;
    cin >> N_input >> K_input;
    K = K_input;

    i64 depth = 0;
    i64 temp = N_input;
    while (temp >= K) {
        depth++;
        temp /= K;
    }

    table[0][0] = Matrix<i64>::identity_matrix(K + 1);
    for (int i = 1; i < K + 1; ++i) table[0][0][0][i] = 1;

    for (int i = 1; i < K; ++i) {
        table[0][i] = table[0][i-1];
        table[0][i].cyclic_shift();
    }

    for (i64 level = 1; level <= depth; ++level) {
        table[level][0] = table[level-1][0];
        for (int i = 1; i < K; ++i) {
            table[level][0] = table[level-1][i] * table[level][0];
        }
        for (int i = 1; i < K; ++i) {
            table[level][i] = table[level][i-1];
            table[level][i].cyclic_shift();
        }
    }

    Matrix<i64> result(K + 1, 1);
    result[K][0] = 1;
    int shift_count = 0;

    while (depth >= 0) {
        for (int i = 0; ; ++i) {
            if (fast_pow(K, depth) <= N_input) {
                N_input -= fast_pow(K, depth);
                result = table[depth][shift_count] * result;
                shift_count = (shift_count + 1) % K;
            } else {
                break;
            }
        }
        depth--;
    }

    i64 sum = 0;
    for (int i = 0; i < K + 1; ++i) {
        sum = (sum + result[i][0]) % MOD;
    }
    cout << sum << '\n';

    return 0;
}
